create table if not exists public.location_discovery_sessions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,latitude double precision not null,longitude double precision not null,accuracy_m double precision default 0,radius_m integer not null default 10000,membership_type text not null default 'consumer',discovered_count integer not null default 0,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now()); create index if not exists idx_location_discovery_sessions_user_time on public.location_discovery_sessions(user_id,created_at desc); alter table public.location_discovery_sessions enable row level security; create policy discovery_sessions_own_insert on public.location_discovery_sessions for insert to authenticated with check(user_id=auth.uid()); create policy discovery_sessions_own_read on public.location_discovery_sessions for select to authenticated using(user_id=auth.uid()); create or replace function public.resolve_nearby_notification_recipients(p_location_id uuid,p_radius_m integer default 10000) returns table(user_id uuid) language sql security definer set search_path=public as $$ with target as (select latitude,longitude from public.locations where id=p_location_id),latest as (select distinct on (ls.user_id) ls.user_id,ls.latitude,ls.longitude from public.location_discovery_sessions ls order by ls.user_id,ls.created_at desc),obs as (select distinct on (lo.observer_user_id) lo.observer_user_id as user_id,lo.latitude,lo.longitude from public.location_observations lo where lo.latitude is not null and lo.longitude is not null order by lo.observer_user_id,lo.observed_at desc),pos as (select coalesce(o.user_id,l.user_id) user_id,coalesce(o.latitude,l.latitude) latitude,coalesce(o.longitude,l.longitude) longitude from latest l full join obs o on o.user_id=l.user_id) select distinct pos.user_id from pos join public.notification_preferences np on np.user_id=pos.user_id cross join target t where coalesce(np.push,true)=true and 111320*sqrt(power((pos.latitude-t.latitude),2)+power((pos.longitude-t.longitude)*cos(radians(t.latitude)),2)) <= p_radius_m; $$;
